type GpuFused = burn::backend::Cuda;
/// CUDA with kernel fusion OFF — the exact inner backend `Cuda` wraps in `Fusion`.
type GpuNoFusion = burn_cubecl::CubeBackend<cubecl::cuda::CudaRuntime, f32, i32, u8>;

