const HIDDEN: usize = 64;
const MID: usize = 9;
const N: usize = 5; // batch size (> 1 is required to trigger the bug)

/// `IN -> HIDDEN -> MID -> 1`, LeakyReLU between, `tanh` on the scalar output.
#[derive(Module, Debug)]
