    fn new(device: &B::Device) -> Self {
        Mlp {
            fc1: LinearConfig::new(IN, HIDDEN).init(device),
            fc2: LinearConfig::new(HIDDEN, MID).init(device),
            fc3: LinearConfig::new(MID, 1).init(device),
            act: LeakyReluConfig::new().init(),
        }
    }
    fn forward(&self, x: Tensor<B, 2>) -> Tensor<B, 2> {
        let x = self.act.forward(self.fc1.forward(x));
        let x = self.act.forward(self.fc2.forward(x));
        tanh(self.fc3.forward(x)) // [N, 1]
    }
}

type Recorder = NamedMpkFileRecorder<FullPrecisionSettings>;

fn input_data() -> Vec<f32> {
    (0..N * IN).map(|i| (i as f32 * 0.1).sin()).collect()
}
fn encode<B: Backend>(device: &B::Device) -> Tensor<B, 2> {
    Tensor::<B, 1>::from_floats(input_data().as_slice(), device).reshape([N, IN])
}
fn to_vec<B: Backend>(t: Tensor<B, 2>) -> Vec<f32> {
    t.into_data().to_vec::<f32>().unwrap()
}
fn maxdiff(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b).map(|(x, y)| (x - y).abs()).fold(0.0f32, f32::max)
}

fn main() {
    let cpu_dev = Default::default();
    let fused_dev = Default::default();
    let nofus_dev = Default::default();

    // Build the net once on the CPU and persist it, so every backend loads the
    // *same* weights (fresh random init differs per backend/RNG otherwise).
    Cpu::seed(&cpu_dev, 1);
    let net_cpu = Mlp::<Cpu>::new(&cpu_dev);
    let stem = std::env::temp_dir().join(format!("burn_fusion_narrow_{}", std::process::id()));
    net_cpu.clone().save_file(&stem, &Recorder::new()).expect("save net");

    let net_cpu = net_cpu.load_file(&stem, &Recorder::new(), &cpu_dev).expect("reload cpu");
    let net_fused = Mlp::<GpuFused>::new(&fused_dev)
        .load_file(&stem, &Recorder::new(), &fused_dev).expect("load fused");
    let net_nofus = Mlp::<GpuNoFusion>::new(&nofus_dev)
        .load_file(&stem, &Recorder::new(), &nofus_dev).expect("load un-fused");

    let out_cpu = to_vec(net_cpu.forward(encode::<Cpu>(&cpu_dev)));
    let out_nofus = to_vec(net_nofus.forward(encode::<GpuNoFusion>(&nofus_dev)));
    let out_fused = to_vec(net_fused.forward(encode::<GpuFused>(&fused_dev)));

